from pathlib import Path
import json
root=Path(__file__).resolve().parents[1]
data=json.loads((root/'catalog.json').read_text())
light=[{k:c[k] for k in ['id','title','tags','beats','source','frames','duration']} for c in data]
html='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tables 本地动画参考库</title><style>
*{box-sizing:border-box}body{margin:0;background:#f4f3ee;color:#242631;font:16px -apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif}header{padding:38px 5vw 24px;border-bottom:1px solid #ddd;background:#fff}h1{font-size:32px;margin:0 0 12px}p{line-height:1.65;color:#666}input{font:inherit;width:min(650px,100%);padding:13px 17px;border:1px solid #ccc;border-radius:8px}main{padding:28px 5vw;display:grid;grid-template-columns:repeat(auto-fill,minmax(310px,1fr));gap:22px}.card{padding:0;overflow:hidden;background:white;border:1px solid #ddd;border-radius:10px;text-align:left;color:inherit;cursor:pointer}.card img{display:block;width:100%;aspect-ratio:16/9;object-fit:cover;background:#eee}.meta{padding:16px}.meta h2{font-size:19px;margin:0 0 10px}.meta p{font-size:13px;margin:0}.badge{font-size:12px;color:#7261c0;margin-left:10px}dialog{width:min(1100px,95vw);max-height:95vh;border:0;border-radius:14px;padding:24px;background:#faf9f6}dialog::backdrop{background:#000a}.top{display:flex;align-items:center;justify-content:space-between}button{font:inherit}#close{padding:8px 18px}video{display:block;width:100%;max-height:63vh;background:#eee}#story{width:100%;display:block}a{color:#5b50bc}nav{display:flex;gap:24px;flex-wrap:wrap;padding:15px 0}#count{margin-left:15px;color:#777;font-size:14px}summary{cursor:pointer;padding:14px 0}footer{padding:20px 5vw 40px;color:#777;font-size:14px}</style>
<header><h1>Tables 本地动画参考库</h1><p>43 个可运行案例 · 每项包含源码、按动作长度导出的视频和四张分镜<br>依据 TypeMotion 公开预览独立重写，非官方源码或逐像素复刻。筛选后点击观看；仅加载选中视频。</p><input id="q" aria-label="搜索案例" placeholder="搜索：趋势、占比、关系、排序、转化……"><span id="count"></span></header><main id="cards"></main><footer>案例是创作参考，不是固定栏目模板。示例数据、配色与时间需按本期内容调整。</footer>
<dialog id="detail"><div class="top"><h2 id="title"></h2><button id="close">关闭</button></div><video id="video" controls playsinline preload="none"></video><p id="beats"></p><nav id="links"></nav><details><summary>查看四张分镜（按各案例动作进度截取）</summary><img id="story" loading="lazy"></details></dialog>
<script>const cases=__DATA__;const $=id=>document.getElementById(id);function show(c){$('title').textContent=c.title;$('video').src=`cases/${c.id}/preview.mp4`;$('video').poster=`cases/${c.id}/frames/${String(c.frames[3]).padStart(3,'0')}.png`;$('story').src=`cases/${c.id}/storyboard.jpg`;$('beats').textContent=c.beats.join(' → ');$('links').replaceChildren();for(const [text,href] of [['案例说明',`cases/${c.id}/README.md`],['动画源码入口',`cases/${c.id}/Scene.tsx`],['原站案例',c.source]]){const a=document.createElement('a');a.textContent=text;a.href=href;a.target='_blank';$('links').append(a)}$('detail').showModal()}function filter(){const q=$('q').value.trim().toLowerCase(),found=cases.filter(c=>JSON.stringify(c).toLowerCase().includes(q));$('count').textContent=`${found.length} / 43`;$('cards').replaceChildren();for(const c of found){const b=document.createElement('button');b.className='card';b.setAttribute('aria-label',c.title);const img=new Image();img.src=`cases/${c.id}/frames/${String(c.frames[3]).padStart(3,'0')}.png`;img.loading='lazy';img.alt=c.title;const box=document.createElement('div');box.className='meta';const h=document.createElement('h2');h.textContent=c.title;const p=document.createElement('p');p.textContent=c.tags.join(' · ');box.append(h,p);b.append(img,box);b.onclick=()=>show(c);$('cards').append(b)}}$('q').oninput=filter;$('close').onclick=()=>$('detail').close();$('detail').onclose=()=>{$('video').pause();$('video').removeAttribute('src');$('video').load()};filter();</script></html>'''
(root/'gallery.html').write_text(html.replace('__DATA__',json.dumps(light,ensure_ascii=False)))
